begin;
create table if not exists public.company_presets (id text primary key, company_account_id uuid not null references public.company_accounts(id) on delete cascade, customer_id text, name text not null, state jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), revision bigint not null default 1);
create index if not exists idx_company_presets_company on public.company_presets(company_account_id);
alter table public.company_presets enable row level security;
create or replace function public.check_company_preset_references() returns trigger language plpgsql security definer set search_path=public as $$begin if new.customer_id is not null and not exists(select 1 from public.customers where id=new.customer_id and company_account_id=new.company_account_id) then raise exception 'Preset customer_id must belong to the same company_account_id'; end if; if tg_op='UPDATE' and new.company_account_id<>old.company_account_id then raise exception 'Preset company_account_id cannot be changed'; end if; return new; end$$;
drop trigger if exists trg_company_preset_references on public.company_presets;
create trigger trg_company_preset_references before insert or update on public.company_presets for each row execute procedure public.check_company_preset_references();
revoke all on public.company_presets from anon, authenticated; grant select on public.company_presets to authenticated;
create policy "Preset members read" on public.company_presets for select using (exists(select 1 from public.company_accounts where id=company_account_id and owner_user_id=auth.uid()) or public.is_active_company_member(company_account_id));
create or replace function public.preset_writable(p uuid) returns boolean language sql stable security definer set search_path=public as $$select public.is_company_account_writable(p) and (exists(select 1 from public.company_accounts where id=p and owner_user_id=auth.uid()) or public.is_active_company_member(p))$$;
create or replace function public.create_company_preset(p_id text,p_company uuid,p_customer text,p_name text,p_state jsonb) returns public.company_presets language plpgsql security definer set search_path=public as $$declare v public.company_presets; begin if not public.preset_writable(p_company) then raise exception 'Preset writes are not allowed for this company'; end if; insert into public.company_presets(id,company_account_id,customer_id,name,state) values(p_id,p_company,p_customer,p_name,p_state) returning * into v; return v; end$$;
create or replace function public.update_company_preset(p_id text,p_company uuid,p_name text,p_state jsonb,p_revision bigint) returns public.company_presets language plpgsql security definer set search_path=public as $$declare v public.company_presets; begin if not public.preset_writable(p_company) then raise exception 'Preset writes are not allowed for this company'; end if; update public.company_presets set name=p_name,state=p_state,revision=revision+1,updated_at=now() where id=p_id and company_account_id=p_company and revision=p_revision returning * into v; if not found then raise exception 'Preset changed or no longer exists'; end if; return v; end$$;
create or replace function public.delete_company_preset(p_id text,p_company uuid,p_revision bigint) returns void language plpgsql security definer set search_path=public as $$begin if not public.preset_writable(p_company) then raise exception 'Preset writes are not allowed for this company'; end if; delete from public.company_presets where id=p_id and company_account_id=p_company and revision=p_revision; if not found then raise exception 'Preset changed or no longer exists'; end if; end$$;
grant execute on function public.create_company_preset(text,uuid,text,text,jsonb),public.update_company_preset(text,uuid,text,jsonb,bigint),public.delete_company_preset(text,uuid,bigint) to authenticated; commit;
